(()=>{const n=document.querySelectorAll("[data-github-repo]"),e=new Map,s=60*60*1e3,t=new Intl.NumberFormat("zh-CN");function o(e){try{const t=JSON.parse(sessionStorage.getItem(`github-card:${e}`));if(t&&Date.now()-t.time<s&&t.data)return t.data}catch{}return null}async function i(e){const t=o(e);if(t)return t;const n=new AbortController,s=setTimeout(()=>n.abort(),8e3);try{const s=await fetch(`https://api.github.com/repos/${e}`,{headers:{Accept:"application/vnd.github+json"},signal:n.signal,credentials:"omit",referrerPolicy:"no-referrer"});if(!s.ok)throw new Error(`GitHub HTTP ${s.status}`);const t=await s.json();if(typeof t.stargazers_count!="number"||typeof t.forks_count!="number")throw new Error("Invalid repository response");const o={description:typeof t.description=="string"?t.description:"",stars:t.stargazers_count,forks:t.forks_count,license:t.license?.spdx_id==="NOASSERTION"?t.license.name||"未指定":t.license?.spdx_id||"未指定"};try{sessionStorage.setItem(`github-card:${e}`,JSON.stringify({time:Date.now(),data:o}))}catch{}return o}finally{clearTimeout(s)}}n.forEach(n=>{const s=n.dataset.githubRepo;if(!/^[A-Za-z0-9][A-Za-z0-9-]*\/[A-Za-z0-9_.-]+$/.test(s))return;const o=n.querySelector("[data-repo-status]");o.textContent="加载中…",e.has(s)||e.set(s,i(s)),e.get(s).then(e=>{e.description&&(n.querySelector("[data-repo-description]").textContent=e.description),n.querySelector("[data-repo-stars]").textContent=t.format(e.stars),n.querySelector("[data-repo-forks]").textContent=t.format(e.forks),n.querySelector("[data-repo-license]").textContent=e.license,o.textContent="GitHub"}).catch(()=>{o.textContent="点击查看详情"})})})()